window.ME_DATA = window.ME_DATA || {};
window.ME_DATA["y7-me"] = [
 {
  id:"l1", lesson:1, title:"Fairness, Equality & Overcoming Prejudice", unit:"Unit 1: Character & Morality", art:"fair",
  dna:"Picture two classrooms. In the first, every student gets exactly the same size chair. In the second, each student gets a chair sized to fit them. Write one word to describe each classroom, then answer in one sentence: is 'the same for everyone' always fair?",
  dnaQs:["One word to describe the classroom where everyone gets the same size chair:","One word to describe the classroom where each chair is sized to fit the student:","Is 'the same for everyone' always fair? Answer in one sentence."],
  dnaHint:"A good answer notices that the same-size chairs are equal but may not fit everyone, while the sized chairs give each student what they need. 'The same for everyone' is not always fair, because people have different needs.",
  intentions:["Understand what fairness and equality mean, and why treating people 'the same' is not always fair.","Explore how social background can affect tolerance, respect and equality.","Identify personal prejudices and strategies to overcome them."],
  criteria:["I can outline the problems that can arise when considering equality.","I can describe the contested nature of reasoning about what is fair.","I can explain how social background can affect tolerance, respect and equality.","I can list personal prejudices and recommend strategies to overcome them."],
  concept:{key:"Global Interactions", related:"Fairness, Equity & Rights", soi:"Exploring fairness and equity within relationships helps individuals build more just and respectful communities.", context:"Fairness and Development — exploring rights, equality and the distribution of resources and opportunity.", uae:"UAE Constitution — Article 25 (equality before the law); links to English (persuasive writing) and Individuals & Societies."},
  words:[["Fairness","Treating people in a way that is right and reasonable, considering everyone's needs."],["Equality","Giving everyone the same rights, opportunities and treatment."],["Equity","Giving people what they need to have fair access to the same opportunities (not always 'the same')."],["Distributive justice","The fair allocation of resources, such as wealth, work or positions, across a group or community."],["Prejudice","A judgement or opinion formed about a person or group without enough knowledge, thought or reason."],["Tolerance","Willingness to accept beliefs, customs or behaviour that are different from one's own."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Choose ONE real-world example of fairness or unfairness (e.g. access to clean water, pay gaps, disaster aid distribution).","Research your example using at least two reliable sources.","Record: what happened, who was affected, and why it is considered fair or unfair.","Note one strength and one limitation of one of your sources."], prompts:["What happened?","Who was affected?","Why is it considered fair or unfair?","One strength and one limitation of one of your sources:"], success:"A strong answer names the group affected, explains the cause of the unfairness (e.g. unequal access to resources, historic disadvantage), and refers to at least one credible source (news article, NGO report, government data)."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"A class teacher has 20 sweets to share between 20 students. Five students missed breakfast and are very hungry; the rest ate a full meal. The teacher decides to give the five hungry students two sweets each, and the rest one sweet each.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain whether the teacher's decision was fair.","Use at least THREE words from the Word Bank (e.g. fairness, equality, equity) accurately in your paragraph.","Include one sentence that considers a different point of view."], model:"The teacher's decision was fair, even though it was not equal. Equality would mean giving every student one sweet, but equity means giving students what they need. Because the five hungry students had not eaten, they needed more, so distributive justice was achieved by giving them two sweets each. However, some students might argue this is unfair because everyone contributed the same amount of effort in class.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; considers an alternative viewpoint."]], starters:["I think the teacher's decision was ___ because ___.","Equality would mean ___, but equity means ___.","However, some students might argue that ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"The Fair Distribution Challenge", steps:["In groups of 3–4, you are given a limited classroom resource (e.g. 10 tablets for 25 students) to distribute across your class.","Design a fair distribution plan. Decide: will you use equality, equity, or a mix of both? Justify your reasoning.","Identify at least one personal bias or assumption your group had to check while deciding, and how you overcame it.","Prepare a 2-minute presentation of your plan, including one visual (diagram, table or poster).","Present to the class and be ready to answer questions that challenge your fairness reasoning."], rubric:[["1–2","Distribution plan lacks reasoning; no bias identified."],["3–4","Basic plan with limited justification; bias named but not explained."],["5–6","Clear plan using equality/equity reasoning; bias identified and briefly explained."],["7–8","Well-justified plan; bias clearly identified with a strategy to overcome it; responds well to challenge questions."]]},
  game:{type:"sort", title:"Equality or Equity?", prompt:"Sort each example: is it equality (everyone gets exactly the same) or equity (people get what they need)?", bins:["Equality","Equity"], items:[["Every student gets exactly the same size chair.",0],["Each student gets a chair sized to fit them.",1],["Every student gets one sweet each.",0],["The five hungry students get two sweets each.",1],["Every person has one vote.",0],["A student who needs it gets extra time to reach the same goal.",1],["Everyone receives the same rights before the law.",0],["Resources go first to the people who have the least access.",1]]},
  quiz:[["What does 'equality' mean?",["Giving everyone the same rights, opportunities and treatment","Giving people what they need to have fair access","Rewarding people for their effort"],0],["What does 'equity' mean?",["Giving everyone exactly the same thing","Giving people what they need to have fair access to the same opportunities","Choosing people at random"],1],["In the sweets story, why could the teacher's decision be called fair?",["Everyone got the same number of sweets","The hungry students had greater need, so they got more","The teacher kept the extra sweets"],1],["What is 'distributive justice'?",["The fair allocation of resources across a group or community","A law about sharing food","A punishment for unfair behaviour"],0],["What is prejudice?",["A fair decision based on evidence","A judgement formed about a person or group without enough knowledge, thought or reason","A tradition passed down through generations"],1],["Which article of the UAE Constitution guarantees equality before the law?",["Article 1","Article 25","Article 100"],1],["Which statement about bias is true according to this lesson?",["Only bad people have biases","Everyone has biases, and naming a bias is the first step to challenging it","Biases cannot be noticed"],1],["Is 'the same for everyone' always fair?",["Yes, always","No — sometimes people need different things to have fair access","Only in sport"],1]],
  exit:"Write ONE sentence using the word 'equity' correctly, and ONE strategy you could personally use to check a bias before it affects a decision you make.",
  copy:{facts:["Equality = giving everyone the same; equity = giving people what they need to have fair access.","Treating people 'the same' is not always fair — reasoning about fairness is contested.","UAE Constitution Article 25 guarantees equality before the law."]},
  next:"Next lesson: we continue Unit 1 by exploring how communities and societies decide what counts as a shared moral rule."
 },
 {
  id:"l2", lesson:2, title:"How Do We Decide What's Fair?", unit:"Unit 1: Character & Morality", art:"reason",
  dna:"Recap: in one sentence, explain the difference between 'equality' and 'equity'. Then read this scenario: a pizza is shared between 4 friends — one hasn't eaten all day, one paid for it, one is the smallest, and one baked it. Who do you think deserves the biggest slice, and why?",
  dnaQs:["In one sentence: what is the difference between equality and equity?","Who deserves the biggest slice of pizza?","Why? Give your reason."],
  dnaHint:"Equality means everyone gets the same; equity means people get what they need. There is no single correct answer about the pizza — the friend who hasn't eaten (need), the one who paid or baked it (merit/contribution) can all be defended. A good answer gives a clear reason.",
  intentions:["Understand different principles people use to decide what is fair (equality, need, merit, rights).","Explore why reasoning about fairness is contested — reasonable people can disagree.","Apply a fairness principle to a real scenario and justify the choice."],
  criteria:["I can name at least three different principles people use to decide what is fair.","I can explain why reasoning about fairness is contested rather than having one right answer.","I can apply a fairness principle to a real scenario and justify my reasoning."],
  concept:{key:"Global Interactions", related:"Fairness, Equity & Rights", soi:"The principles we use to reason about fairness shape the decisions and relationships within a community.", context:"Fairness and Development — exploring rights, equality and the distribution of resources and opportunity.", uae:"Links to English (persuasive/argumentative writing) and Individuals & Societies; builds on Lesson 1's UAE Constitution equality link."},
  words:[["Equality-based","Deciding fairness by giving everyone exactly the same share."],["Need-based","Deciding fairness by giving more to those who need it most."],["Merit-based","Deciding fairness by rewarding effort, skill or contribution."],["Rights-based","Deciding fairness according to an entitlement everyone is owed."],["Contested","Something that is argued about and does not have one agreed answer."],["Justify","To give good reasons for a decision or opinion."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Choose ONE real system that allocates something scarce (e.g. a hospital waiting list, a lottery for school places, university admissions, a queue).","Research how it decides who gets what, using at least two reliable sources.","Identify which fairness principle(s) it mainly uses: equality, need, merit or rights.","Note one criticism people have made of this system's fairness."], prompts:["Which system did you choose?","How does it decide who gets what?","Which fairness principle(s) does it mainly use?","One criticism of this system's fairness:"], success:"A strong answer correctly identifies the main principle (e.g. hospital triage is need-based, a lottery is equality-based, university admissions are merit-based) and notices that many systems actually blend more than one principle."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"A school has only 15 spaces on a trip to the science museum, but 40 students want to go. The school could (a) offer the spaces to the first 15 who sign up, (b) hold a random draw, (c) prioritise students who have never been on a school trip before, or (d) offer them to the 15 students with the best attendance record.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), argue which option (a, b, c or d) is fairest.","Use at least THREE words from the Word Bank (e.g. equality-based, need-based, merit-based, rights-based) accurately.","Include one sentence that acknowledges why someone might disagree with your choice."], model:"Option (c) is the fairest choice. This is because it uses a need-based approach, giving priority to students who have never had the opportunity before, rather than an equality-based approach like first-come-first-served, which could unfairly reward students who simply have faster internet or more free time. However, some people might disagree, arguing that a merit-based system rewarding good attendance is fairer because it recognises effort.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; acknowledges a counter-view."]], starters:["I think option ___ is fairest because it uses a ___-based approach.","This is fairer than option ___ because ___.","However, some people might disagree, arguing that ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Design a Fair System", steps:["In groups of 3–4, you are given a real school scenario (e.g. allocating 5 tickets to a sold-out event among 30 students).","As a group, decide which fairness principle(s) — equality, need, merit, rights — you will combine to build your system.","Design your system as a clear flowchart or set of rules that a teacher could actually use.","Identify one weakness of your system and how you would respond to a student who complained it was unfair.","Prepare a 2-minute presentation, including one visual (flowchart, table or poster)."], rubric:[["1–2","System lacks clear reasoning; no weakness identified."],["3–4","Basic system with limited justification; weakness named but not explained."],["5–6","Clear system combining at least one named principle; weakness identified and briefly explained."],["7–8","Well-justified system combining principles thoughtfully; weakness clearly explained with a considered response to challenge."]]},
  game:{type:"sort", title:"Which Fairness Principle?", prompt:"Sort each example into the fairness principle it mainly uses.", bins:["Equality-based","Need-based","Merit-based","Rights-based"], items:[["One vote per person.",0],["A random draw for trip places.",0],["Hospital triage treats the most urgent patients first.",1],["Trip places go to students who have never been on a trip.",1],["University places go to students with the best exam results.",2],["Trip places go to the students with the best attendance.",2],["Everyone is entitled to a fair trial.",3],["Refugee resettlement quotas based on entitlement.",3]]},
  quiz:[["Which principle decides fairness by giving more to those who need it most?",["Merit-based","Need-based","Equality-based"],1],["Which principle rewards effort, skill or contribution?",["Merit-based","Rights-based","Need-based"],0],["Hospital triage is mainly an example of which principle?",["Equality-based","Merit-based","Need-based"],2],["What does 'contested' mean?",["Argued about, with no one agreed answer","Proven by science","Against the law"],0],["What does 'justify' mean?",["To give good reasons for a decision or opinion","To choose at random","To agree with everyone"],0],["A random draw (lottery) for school places mainly uses which principle?",["Need-based","Equality-based","Merit-based"],1],["Which statement about real-world systems is true?",["They always use just one principle","Many blend two or more principles","They never use need"],1],["Why is reasoning about fairness called 'contested'?",["Because reasonable people can disagree about which principle is fairest","Because fairness is not important","Because only judges can decide"],0]],
  exit:"Name the fairness principle you found hardest to disagree with today, and explain in one sentence why it convinced you.",
  copy:{facts:["Four fairness principles: equality-based, need-based, merit-based and rights-based.","Reasoning about fairness is contested — reasonable people can disagree.","Most real systems blend more than one principle."]},
  next:"Next lesson: we continue Unit 1 by exploring how social background can affect tolerance, respect and equality."
 },
 {
  id:"l3", lesson:3, title:"Social Background, Tolerance & Respect", unit:"Unit 1: Character & Morality", art:"tolerance",
  dna:"Recap: name one fairness principle from last lesson (equality, need, merit or rights). Now think: two students apply for the same scholarship. One has private tutors and a quiet study room; the other works after school and shares a bedroom with three siblings. Write one way their backgrounds might affect their chances — even if both work equally hard.",
  dnaQs:["Name one fairness principle from last lesson:","One way their backgrounds might affect their chances:"],
  dnaHint:"Any of equality, need, merit or rights is correct. A good answer notices that the student with tutors and a quiet room has more support and time to study, while the student who works and shares a room has less time and space — so background can affect opportunity even when effort is the same.",
  intentions:["Understand what 'social background' means and its different aspects.","Explore how social background can foster or undermine tolerance, respect and equality.","Reflect on how our own background can shape our perspective and assumptions."],
  criteria:["I can define social background and identify some of its different aspects.","I can explain how social background can affect tolerance, respect and equality.","I can reflect on how my own background may shape my perspective."],
  concept:{key:"Global Interactions", related:"Fairness, Equity & Rights", soi:"The social background of individuals and communities can foster or undermine tolerance, respect and equality within relationships.", context:"Fairness and Development — exploring rights, equality and the distribution of resources and opportunity.", uae:"Links to Individuals & Societies (social structures) and English (empathetic/perspective writing); the UAE's diverse population of 200+ nationalities makes this especially relevant locally."},
  words:[["Social background","The mix of family, community, upbringing and circumstances a person grows up in."],["Social class","A way of grouping people based on factors such as income, occupation or education."],["Perspective","A particular way of viewing or understanding something, shaped by a person's experiences."],["Tolerance","Willingness to accept beliefs, customs or behaviour that are different from one's own."],["Empathy","The ability to understand and share the feelings of another person."],["Opportunity","A chance or set of circumstances that makes it possible to do something."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Choose ONE area where background can affect opportunity (e.g. access to education, access to healthcare, access to technology).","Research your chosen area using at least two reliable sources.","Record: what the research shows, and one reason background makes a difference in this area.","Note one thing that is being done (by a school, government or organisation) to reduce this gap."], prompts:["Which area did you choose?","What does the research show?","One reason background makes a difference:","One thing being done to reduce the gap:"], success:"A strong answer uses global or national information, cites a statistic or study, and names a real initiative addressing the gap (e.g. scholarship programmes, subsidised internet schemes, free school meals)."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"Amir grew up moving between three countries as his parents' jobs changed. Layla has lived in the same neighbourhood her whole life, surrounded by family. When they meet new people, Amir usually assumes people from different backgrounds will get along fine; Layla is more cautious with people whose customs she doesn't recognise.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain how each character's background may have shaped their attitude to new people.","Use at least THREE words from the Word Bank (e.g. social background, perspective, tolerance) accurately.","Include one sentence reflecting on how your own background might shape your first reactions to someone different from you. (Your reflection stays private unless you choose to share it.)"], model:"Amir's background, moving between countries, has given him regular practice meeting people from different backgrounds, which may explain his tolerance and confidence around new people. Layla's background, staying in one close-knit community, means she has had less exposure to different customs, which could explain her caution — not because she is unkind, but because the unfamiliar feels riskier. My own background shapes my first reactions too: growing up around similar people to me might make me quicker to notice differences than someone who has always lived somewhere diverse.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; genuine personal reflection included."]], starters:["Amir's social background may explain his ___ because ___.","Layla's caution could come from ___, not because ___.","My own background might shape my first reactions because ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Perspective Profiles", steps:["In groups of 3–4, you will each be given a fictional character profile with a different social background.","As a group, discuss how each character's background might shape their views on tolerance, respect and equality.","Create a short 'perspective profile' poster for each character: their background, one assumption they might make, and one experience that could challenge that assumption.","Identify one thing all four characters could do to better understand each other.","Present your four perspective profiles to the class in a 3-minute group presentation."], rubric:[["1–2","Profiles are generic; no clear link to background made."],["3–4","Profiles show a basic link between background and one assumption."],["5–6","Profiles clearly link background to assumptions and to a challenging experience."],["7–8","Profiles are insightful and nuanced; group proposes a genuine, thoughtful way for the characters to understand each other."]]},
  game:{type:"sort", title:"Fair Thinking or Assumption?", prompt:"Sort each statement: does it show a fair way to think about social background, or an unfair assumption?", bins:["Fair thinking","Unfair assumption"], items:[["Everyone's background shapes their perspective, including mine.",0],["Some backgrounds are simply better than others.",1],["Being cautious with unfamiliar customs can come from unfamiliarity, not unkindness.",0],["Only other people have a background that shapes their views.",1],["Meeting people from different backgrounds can increase tolerance.",0],["If two students work equally hard, their backgrounds make no difference at all.",1],["Backgrounds are different, not ranked.",0],["Anyone who is cautious with new customs must be prejudiced.",1]]},
  quiz:[["What is 'social background'?",["The mix of family, community, upbringing and circumstances a person grows up in","The country on your passport only","Your favourite hobbies"],0],["What does 'empathy' mean?",["Disagreeing politely","The ability to understand and share the feelings of another person","Giving everyone the same share"],1],["What is a 'perspective'?",["A fact everyone agrees on","A particular way of viewing something, shaped by a person's experiences","A type of school subject"],1],["In the extract, why might Amir be confident around new people?",["He has had regular practice meeting people from different backgrounds","He has lived in one neighbourhood all his life","He doesn't care about others"],0],["Why might Layla be more cautious?",["She is unkind","She has had less exposure to different customs, so the unfamiliar feels riskier","She dislikes everyone"],1],["Roughly how many nationalities live in the UAE?",["About 20","Over 200","Exactly 50"],1],["Which statement is true?",["Only some people have a background that shapes their views","Everyone's background shapes their perspective","Background never affects opportunity"],1],["Which is an example of how background can affect opportunity?",["Having a quiet study room and tutors versus sharing a bedroom and working after school","Liking pizza more than pasta","Being born on a Monday"],0]],
  exit:"Write ONE way you could show more tolerance toward someone whose background is very different from your own.",
  copy:{facts:["Social background = the mix of family, community, upbringing and circumstances a person grows up in.","Background shapes everyone's perspective — backgrounds are different, not ranked.","The UAE is home to over 200 nationalities."]},
  next:"Next lesson: we continue Unit 1 by identifying personal prejudices and strategies to overcome them."
 },
 {
  id:"l4", lesson:4, title:"Personal Prejudice & Strategies to Overcome It", unit:"Unit 1: Character & Morality", art:"prejudice",
  dna:"Recap: in one sentence, explain what 'social background' means. Then, privately, think of a time you made a snap judgement about someone before really knowing them. You don't have to describe it — just notice that it happened. Everyone does this; today we learn what to do about it.",
  dnaQs:["In one sentence: what does 'social background' mean?","Without giving details, why do you think people sometimes make snap judgements about others?"],
  dnaHint:"Social background is the mix of family, community, upbringing and circumstances a person grows up in. Snap judgements often happen because our brains take shortcuts — grouping people quickly or favouring what is familiar. Everyone does it; the important part is noticing it.",
  intentions:["Understand what personal prejudice is and how it can form.","Explore practical strategies to notice and challenge personal prejudice.","Apply a chosen strategy to a realistic scenario."],
  criteria:["I can explain what personal prejudice is and how it can form.","I can list at least two strategies to challenge personal prejudice.","I can apply a strategy to a realistic scenario and justify my choice."],
  concept:{key:"Global Interactions", related:"Fairness, Equity & Rights", soi:"Recognising and challenging personal prejudice helps individuals build fairer, more respectful relationships.", context:"Fairness and Development — exploring rights, equality and the distribution of resources and opportunity.", uae:"Links to the UAE's national values of tolerance (Ministry of Tolerance and Coexistence); links to English (persuasive/reflective writing)."},
  words:[["Prejudice","A judgement or opinion formed about a person or group without enough knowledge, thought or reason."],["Bias","A tendency to lean toward or against something, often without realising it."],["Stereotype","An oversimplified, fixed idea about a whole group of people."],["Assumption","Something accepted as true without being checked or proven."],["Challenge (verb)","To question or test whether a belief or assumption is actually true."],["Strategy","A planned approach used to achieve a goal, such as reducing bias."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Choose ONE real strategy an organisation uses to reduce bias (e.g. blind recruitment, diverse hiring panels, unconscious-bias training).","Research it using at least two reliable sources.","Record: how the strategy works, and what type of bias it is designed to reduce.","Note one strength and one limitation of the strategy."], prompts:["Which strategy did you choose?","How does the strategy work?","What type of bias is it designed to reduce?","One strength and one limitation:"], success:"A strong answer names the specific type of bias targeted (e.g. blind CV screening removes names and photos to reduce hiring bias) and cites a real organisation or study."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"Sara was about to pick teams for a class project. Without thinking, she was about to choose the same three friends she always works with. She paused and realised she hadn't even considered anyone else — not because they weren't capable, but because they weren't the people she usually noticed.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain what kind of bias Sara noticed in herself.","Use at least THREE words from the Word Bank (e.g. bias, assumption, strategy) accurately.","Recommend ONE strategy Sara could use next time she picks a team, and explain why it would help."], model:"Sara noticed a bias called 'familiarity bias' — automatically choosing people she already knows well, rather than considering everyone fairly. This is an assumption because she hadn't actually thought about whether her friends were the best choice, she just defaulted to habit. Next time, Sara could use a 'pause and check' strategy: before picking a team, she could briefly list everyone available and ask herself why she is choosing who she chooses. This would help her notice her bias before acting on it.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; recommended strategy is specific and justified."]], starters:["Sara's bias was ___.","This is because ___.","Next time, she could ___.","This would help because ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Bias-Busters Campaign", steps:["In groups of 3–4, choose ONE everyday situation where bias can creep in (picking teams, giving opinions on new students, forming first impressions).","Choose ONE strategy from today's lesson (or your Task 1 research) that could help.","Design a short awareness campaign for your year group: a poster, slogan and one clear action step.","Explain why your chosen strategy is practical for students your age to actually use.","Present your campaign to the class in a 2-minute pitch."], rubric:[["1–2","Campaign lacks a clear strategy or action step."],["3–4","Basic campaign with a named strategy but limited explanation."],["5–6","Clear campaign with a named strategy, explained and reasonably practical."],["7–8","Well-designed, practical campaign; strategy is clearly explained and convincingly justified for the target audience."]]},
  game:{type:"sort", title:"Bias or Strategy?", prompt:"Sort each example: is it a bias creeping in, or a strategy to challenge bias?", bins:["Bias creeping in","Strategy to challenge bias"], items:[["Always picking the same friends without thinking about anyone else.",0],["Pausing to notice a snap judgement before acting on it.",1],["Deciding what a whole group is like from one example.",0],["Imagining the situation from the other person's point of view.",1],["Thinking of examples that challenge a stereotype.",1],["Judging a new student before getting to know them.",0],["Spending more time with people from different backgrounds.",1],["Removing names from applications so they are judged fairly.",1]]},
  quiz:[["What is a stereotype?",["An oversimplified, fixed idea about a whole group of people","A fair judgement based on evidence","A type of music player"],0],["What is an assumption?",["Something checked and proven","Something accepted as true without being checked or proven","A planned approach to a goal"],1],["What does 'bias' mean?",["A tendency to lean toward or against something, often without realising it","A tradition passed down through generations","A rule everyone agrees on"],0],["What kind of bias did Sara notice?",["Familiarity bias — choosing people she already knows well","Weather bias","Height bias"],0],["Which is one of the four strategies from this lesson?",["Ignore it","Pause and check","Always pick friends"],1],["What does 'perspective-taking' mean?",["Taking a photograph","Imagining the situation from the other person's point of view","Choosing the biggest group"],1],["Which statement about bias is true?",["Having a bias makes you a bad person","Everyone has some bias; the goal is noticing and interrupting it","Bias is only about race or religion"],1],["Why do some orchestras and organisations use 'blind' processes?",["Because bias can operate without people realising it","To save money on lights","Because names are not important to anyone"],0]],
  exit:"Which of the four strategies (pause and check, perspective-taking, seek counter-examples, increase exposure) will you try this week, and in what situation?",
  copy:{facts:["Prejudice is a judgement formed without enough knowledge, thought or reason.","Everyone has some bias — the goal is to notice it and challenge it.","Four strategies: pause and check, perspective-taking, seek counter-examples, increase exposure."]},
  next:"Next lesson: we continue Unit 1 by exploring reasons to respect the beliefs, values and traditions of others."
 },
 {
  id:"l5", lesson:5, title:"Respecting Beliefs, Values & Traditions", unit:"Unit 1: Character & Morality", art:"traditions",
  dna:"Recap: in one sentence, name one strategy for challenging personal bias from last lesson. Then think of ONE tradition or celebration you know of that isn't your own family's (e.g. a festival, food custom or ceremony). Write what you already know about why it matters to the people who celebrate it.",
  dnaQs:["One strategy for challenging personal bias:","A tradition or celebration you know of (not your own family's):","Why does it matter to the people who celebrate it?"],
  dnaHint:"Strategies include pause and check, perspective-taking, seeking counter-examples or increasing exposure. A good answer about the tradition goes beyond what happens on the surface and explains its meaning — for example identity, belonging, family or history.",
  intentions:["Understand what beliefs, values and traditions are, and why they matter to people.","Explore reasons why respecting others' beliefs and traditions is important.","Reflect on how to show respect for a tradition different from your own."],
  criteria:["I can define beliefs, values and traditions, with examples.","I can give at least two reasons why respecting others' beliefs and traditions matters.","I can describe a respectful way to engage with a tradition different from my own."],
  concept:{key:"Global Interactions", related:"Fairness, Equity & Rights", soi:"Respecting the beliefs, values and traditions of others builds stronger, more inclusive communities.", context:"Fairness and Development — exploring rights, equality and the distribution of resources and opportunity.", uae:"The UAE's Year of Tolerance and Ministry of Tolerance and Coexistence; links to Individuals & Societies (culture and heritage) and English."},
  words:[["Belief","Something a person accepts or trusts to be true, often without needing physical proof."],["Value","A principle or standard that a person or community sees as important."],["Tradition","A custom or practice passed down through generations."],["Respect","Recognising the worth of something or someone, even without necessarily agreeing with it."],["Heritage","The traditions, achievements and history that belong to a culture or nation."],["Diversity","The presence of a wide range of different people, beliefs or traditions in one place."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Choose ONE tradition, celebration or custom — from the UAE or elsewhere in the world (it does not have to be your own).","Research it using at least two reliable, respectful sources.","Record: what happens during this tradition, and why it matters to the people who practise it.","Note one way a visitor or outsider could show respect when encountering this tradition."], prompts:["Which tradition did you choose?","What happens during this tradition?","Why does it matter to the people who practise it?","One way a visitor could show respect:"], success:"A strong answer uses respectful, accurate language (avoiding words like 'weird' or 'exotic'), cites credible sources (official tourism/culture boards, established encyclopaedic sources), and explains the tradition's real significance rather than just surface details."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"Omar noticed his new classmate, Wei, quietly stepping away from the lunch table during a certain time each day to pray. Omar had never seen this before and felt a little confused, but decided to simply say nothing unkind, wait patiently, and later ask Wei politely what the practice meant to him.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain why Omar's response was respectful.","Use at least THREE words from the Word Bank (e.g. belief, tradition, respect) accurately.","Include one sentence explaining the difference between respecting a belief and agreeing with it."], model:"Omar's response was respectful because he did not judge or interrupt Wei's practice, even though it was unfamiliar to him. Instead, he waited and asked politely, showing genuine interest rather than assumption. This is an example of respecting a belief without necessarily sharing it — respecting a tradition does not mean you have to believe or practise it yourself, only that you accept another person's right to hold it.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; clearly distinguishes respecting from agreeing."]], starters:["Omar's response was respectful because ___.","Instead of making an assumption, he ___.","Respecting a belief is different from agreeing with it because ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Traditions Showcase", steps:["In groups of 3–4, choose 2–3 different traditions to showcase (using Task 1 research as a starting point, plus one new one).","For each tradition, create a poster section with: what it is, why it matters, and one 'respect guideline' for someone encountering it for the first time.","Make sure your traditions come from at least two different regions or cultures, including at least one from the UAE.","Check your language is respectful and accurate — avoid words that could sound judgemental (e.g. 'strange', 'weird').","Present your showcase to the class in a 3-minute group presentation."], rubric:[["1–2","Traditions described with little accuracy or respect guideline missing."],["3–4","Traditions described accurately; basic respect guideline given."],["5–6","Traditions explained with clear significance; respect guidelines are specific and useful."],["7–8","Traditions explained with depth and nuance; respect guidelines are genuinely practical; language is consistently respectful throughout."]]},
  game:{type:"sort", title:"Respectful or Not?", prompt:"Sort each response to an unfamiliar tradition: is it respectful or disrespectful?", bins:["Respectful","Disrespectful"], items:[["Waiting patiently and later asking a polite question.",0],["Calling a tradition 'weird' or 'strange'.",1],["Accepting someone's right to hold a belief you don't share.",0],["Interrupting someone while they practise their tradition.",1],["Using accurate, respectful sources to learn about a tradition.",0],["Assuming something is wrong just because it is unfamiliar.",1],["Saying it is simply different from what I know.",0],["Ranking traditions as 'better' or 'worse'.",1]]},
  quiz:[["What is a tradition?",["A custom or practice passed down through generations","A new rule made yesterday","A school subject"],0],["What does 'respect' mean in this lesson?",["Always agreeing with someone","Recognising the worth of something or someone, even without necessarily agreeing with it","Copying someone's beliefs"],1],["What is a 'value'?",["A principle or standard that a person or community sees as important","The price of an item","A type of celebration"],0],["Why was Omar's response respectful?",["He laughed at Wei","He did not judge, waited patiently and asked politely","He told Wei to stop"],1],["Does respecting a belief mean you must agree with it?",["Yes, always","No — you accept the other person's right to hold it","Only if it is your own family's"],1],["Which year did the UAE designate as the 'Year of Tolerance'?",["2019","2001","2030"],0],["What does the Abrahamic Family House in Abu Dhabi contain side by side?",["A mosque, a church and a synagogue","Three museums","Three schools"],0],["Which is a reason to respect others' traditions?",["Reciprocity: we expect others to respect our beliefs too","Traditions are not important","It means you have to follow them"],0]],
  exit:"Write ONE respectful question you could ask someone about a tradition you don't understand, instead of making an assumption.",
  copy:{facts:["Respecting a tradition does not mean you have to agree with or practise it.","Traditions give people identity, belonging and connection to their history.","The UAE named 2019 the 'Year of Tolerance' and has a Ministry of Tolerance and Coexistence."]},
  next:"Next lesson: we complete Unit 1 by putting respect into practice — treating peers as equals every day."
 },
 {
  id:"l6", lesson:6, title:"Respecting Peers as Equals — Putting It Into Practice", unit:"Unit 1: Character & Morality", art:"respect",
  dna:"Unit 1 vocabulary check! Match each term to its definition as fast as you can: Equity, Prejudice, Tradition, Bias, Perspective. This is our final lesson of Unit 1 — let's see how much has stuck.",
  dnaQs:["Equity means…","Prejudice means…","Tradition means…","Bias means…","Perspective means…"],
  dnaHint:"Equity: giving people what they need to have fair access. Prejudice: a judgement formed without enough knowledge, thought or reason. Tradition: a custom passed down through generations. Bias: a tendency to lean toward or against something, often without realising it. Perspective: a way of viewing something, shaped by your experiences.",
  intentions:["Consolidate understanding of fairness, respect and tolerance from across Unit 1.","Demonstrate practical ways to treat peers as equals in everyday interactions.","Reflect on how thinking about fairness and respect has developed this unit."],
  criteria:["I can correctly match key Unit 1 vocabulary to their definitions.","I can demonstrate at least two practical ways to treat peers as equals in the classroom.","I can reflect on how my thinking about fairness and respect has developed this unit."],
  concept:{key:"Global Interactions", related:"Fairness, Equity & Rights", soi:"Demonstrating respect for differences while treating others as equals turns understanding into everyday practice within a community.", context:"Fairness and Development — exploring rights, equality and the distribution of resources and opportunity.", uae:"Draws together UAE Constitution equality principles (Lesson 1), UAE tolerance values (Lesson 5) and Individuals & Societies; sets up Term 2's Unit 2: The Individual & the Community."},
  words:[["Equality / Equity","Treating everyone the same, vs. giving people what they individually need (Lessons 1–2)."],["Fairness principles","Equality-, need-, merit- and rights-based reasoning about what is fair (Lesson 2)."],["Social background","The mix of family, community and circumstances that shapes perspective (Lesson 3)."],["Prejudice / Bias","A judgement formed without enough knowledge; a strategy can help challenge it (Lesson 4)."],["Tradition / Respect","A custom passed through generations; respecting it doesn't require agreeing with it (Lesson 5)."],["Inclusion","Making sure everyone feels and is treated as a valued, equal member of a group (new today)."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Find ONE real 'respect charter', code of conduct or set of community values from a school, sports team or organisation.","Research it using at least two reliable sources.","Record: three specific, practical actions it asks people to take (not just vague statements).","Note whether it connects to any Unit 1 idea (fairness, tolerance, respecting differences).","Your findings will feed directly into Task 3."], prompts:["Which charter or code of conduct did you choose?","Three specific, practical actions it asks people to take:","Does it connect to a Unit 1 idea? Which one?"], success:"A strong answer picks out concrete actions ('listen without interrupting', 'report concerns to a trusted adult') rather than vague slogans ('be kind'), and makes a genuine link to a Unit 1 idea."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"", steps:["My Respect Pledge: write a structured paragraph (topic sentence, three specific actions, conclusion) that is your personal pledge for treating peers as equals.","Use at least FOUR words from across Unit 1's Word Bank (any lesson) accurately.","Make each action specific and realistic — not just 'be nice', but something you could actually do this week."], model:"This unit has taught me that respecting others as equals means recognising that everyone's background, beliefs and perspective are shaped by different experiences, and that fairness doesn't always mean treating everyone identically. One thing I will do differently is pause and check my assumptions before judging someone, because I've learned that bias often happens automatically. I will also make an effort to include classmates I don't usually work with, using an equity-based approach rather than always defaulting to familiar friends.", rubric:[["1–2","Limited structure; little/no key vocabulary used; vague actions."],["3–4","Basic paragraph structure; 1–2 key terms used; actions somewhat vague."],["5–6","Clear paragraph structure; 3 key terms used mostly accurately; actions are fairly specific."],["7–8","Well-structured paragraph; 4+ key terms used accurately across multiple lessons; actions are specific, realistic and genuinely reflective."]], starters:["This unit has taught me that respecting others as equals means ___.","One thing I will do differently is ___, because ___.","I will also ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Our Class Respect Charter", steps:["As a whole class, pool ideas from Task 1 research and Task 2 pledges.","In small groups, draft 2–3 concrete 'charter' statements covering: fairness, respecting differences, and challenging bias (drawing on Lessons 1–5).","As a class, agree on a final combined list of 6–8 statements for the class Respect Charter.","Design the charter as a poster to be displayed in the classroom for the rest of the year.","Each student signs the charter as a personal commitment."], rubric:[["1–2","Charter statements are vague or generic; little connection to unit learning."],["3–4","Charter statements are basic but relevant; limited connection to specific unit ideas."],["5–6","Charter statements are specific and clearly connect to unit ideas (fairness, respect, bias)."],["7–8","Charter statements are specific, practical and insightful; clear, well-justified connections across multiple unit lessons."]]},
  game:{type:"sort", title:"Specific Action or Vague Slogan?", prompt:"A good respect charter uses specific, practical actions. Sort each statement.", bins:["Specific action","Vague slogan"], items:[["Listen without interrupting.",0],["Be kind.",1],["Report concerns to a trusted adult.",0],["Be nice.",1],["Invite a classmate I don't usually work with to join my group.",0],["Pause and check my assumptions before judging someone.",0],["Be a good person.",1],["Ask a polite question about a tradition I don't understand.",0]]},
  quiz:[["What does 'inclusion' mean?",["Making sure everyone feels and is treated as a valued, equal member of a group","Only working with your friends","Giving everyone exactly the same thing"],0],["What are the four fairness principles from Lesson 2?",["Equality, need, merit and rights","Speed, size, age and luck","Food, money, time and space"],0],["Does treating people 'as equals' mean treating everyone identically?",["Yes, always","No — sometimes equity means giving people what they need","Only on school trips"],1],["Which is a specific, practical charter action?",["Be kind","Listen without interrupting","Be good"],1],["Respecting a tradition means…",["You must practise it yourself","You accept another person's right to hold it, without necessarily agreeing","You ignore it completely"],1],["What shapes a person's perspective, according to Lesson 3?",["Their social background and experiences","Only their age","Nothing at all"],0],["What is the class Respect Charter meant to be?",["A poster that is finished and forgotten","A living commitment revisited through the year","A list of punishments"],1],["What unit begins in Term 2?",["Unit 2: The Individual & the Community","Unit 3: Space Exploration","Unit 1 again"],0]],
  exit:"Write the ONE statement from our new class Respect Charter that you personally find most important, and why.",
  copy:{facts:["Inclusion means making sure everyone feels and is treated as a valued, equal member of a group.","Treating people as equals does not always mean treating them identically.","A respect charter works best with specific, practical actions — not vague slogans."]},
  next:"Unit 1: Character & Morality is complete! Term 2 begins Unit 2: The Individual & the Community."
 }
];
